def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements the Breadth-First Search (BFS) algorithm with edge weights 
    using a modified approach to find the shortest path in a weighted directed graph.
    """
    if start not in graph or end not in graph:
        return (float('inf'), [])

    queue = deque([(start, 0)])
    visited = {node: (float('inf'), None) for node in graph}
    visited[start] = (0, None)

    while queue:
        current_node, current_distance = queue.popleft()

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < visited[neighbor][0]:
                visited[neighbor] = (distance, current_node)
                queue.append((neighbor, distance))

    path = []
    current_node = end
    while current_node is not None:
        path.append(current_node)
        current_node = visited[current_node][1]
    path.reverse()

    if visited[end][0] == float('inf'):
        return (float('inf'), [])

    return (visited[end][0], path)

