def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements the Floyd-Warshall algorithm to find the shortest path in a weighted directed graph 
    using dynamic programming. The algorithm computes the shortest paths between all pairs of nodes.
    """
    nodes = list(graph.keys())
    distance = {node: {n: float('inf') for n in nodes} for node in nodes}
    next_node = {node: {n: None for n in nodes} for node in nodes}

    for node in nodes:
        distance[node][node] = 0

    for node in graph:
        for neighbor, weight in graph[node]:
            distance[node][neighbor] = weight
            next_node[node][neighbor] = neighbor

    for k in nodes:
        for i in nodes:
            for j in nodes:
                if distance[i][j] > distance[i][k] + distance[k][j]:
                    distance[i][j] = distance[i][k] + distance[k][j]
                    next_node[i][j] = next_node[i][k]

    path = []
    if distance[start][end] == float('inf'):
        return (float('inf'), [])

    current_node = start
    while current_node is not None:
        path.append(current_node)
        current_node = next_node[current_node][end] if current_node != end else None

    return (distance[start][end], path)
